import { providers, Wallet } from 'ethers';
import { ChildTransactionReceipt, ChildToParentMessageStatus } from '@arbitrum/sdk';

const withdrawalTxHash = WITHDRAWAL_TX_HASH;

const parentProvider = new providers.JsonRpcProvider(PARENT_RPC_URL);
const childProvider = new providers.JsonRpcProvider(CHILD_RPC_URL);
const parentSigner = new Wallet(PRIVATE_KEY, parentProvider);

async function main() {
  const receipt = await childProvider.getTransactionReceipt(withdrawalTxHash);
  const childReceipt = new ChildTransactionReceipt(receipt);

  // Passing a signer yields ChildToParentMessageWriter instances, which can execute claims
  const messages = await childReceipt.getChildToParentMessages(parentSigner);
  const message = messages[0];

  // Polls every 30 seconds until the message leaves UNCONFIRMED.
  // On a chain with a live challenge period this call blocks for days —
  // use it in a worker, or poll status() on your own schedule instead.
  const status = await message.waitUntilReadyToExecute(childProvider, 30 * 1000);

  if (status === ChildToParentMessageStatus.CONFIRMED) {
    const executeTx = await message.execute(childProvider);
    const executeReceipt = await executeTx.wait();
    console.log('Claim executed on parent chain:', executeReceipt.transactionHash);
  } else {
    console.log('Message already executed');
  }
}
main();

