import { sanitizePrivateKey } from '@arbitrum/chain-sdk/utils';
import { config } from 'dotenv';
import { createPublicClient, createWalletClient, decodeEventLog, defineChain, encodeEventTopics, http } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';

config();

const ticketId = process.env.WETH_TICKET_ID;
if (!/^0x[0-9a-fA-F]{64}$/.test(ticketId || '')) {
  throw new Error('Set WETH_TICKET_ID in .env to the 0x-prefixed ticket ID from the error');
}

const chainRpc = process.env.CHAIN_RPC || 'http://localhost:8547';
const publicClient = createPublicClient({ transport: http(chainRpc) });
const chainId = await publicClient.getChainId();
const chain = defineChain({
  id: chainId,
  name: 'My L3 Rollup',
  nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
  rpcUrls: { default: { http: [chainRpc] } },
});
const account = privateKeyToAccount(sanitizePrivateKey(process.env.DEPLOYER_PRIVATE_KEY));
const walletClient = createWalletClient({ account, chain, transport: http(chainRpc) });
const retryableAddress = '0x000000000000000000000000000000000000006E';
const retryableAbi = [
  {
    type: 'function',
    name: 'redeem',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'ticketId', type: 'bytes32' }],
    outputs: [{ type: 'bytes32' }],
  },
  {
    type: 'event',
    name: 'RedeemScheduled',
    inputs: [
      { name: 'ticketId', type: 'bytes32', indexed: true },
      { name: 'retryTxHash', type: 'bytes32', indexed: true },
      { name: 'sequenceNum', type: 'uint64', indexed: true },
      { name: 'donatedGas', type: 'uint64', indexed: false },
      { name: 'gasDonor', type: 'address', indexed: false },
      { name: 'maxRefund', type: 'uint256', indexed: false },
      { name: 'submissionFeeRefund', type: 'uint256', indexed: false },
    ],
  },
];

const hash = await walletClient.writeContract({
  address: retryableAddress,
  abi: retryableAbi,
  functionName: 'redeem',
  args: [ticketId],
});
const receipt = await publicClient.waitForTransactionReceipt({ hash });
if (receipt.status !== 'success') throw new Error(`Redeem transaction failed: ${hash}`);
const eventTopic = encodeEventTopics({ abi: retryableAbi, eventName: 'RedeemScheduled' })[0];
const scheduled = receipt.logs
  .filter((log) => log.address.toLowerCase() === retryableAddress.toLowerCase() && log.topics[0] === eventTopic)
  .map((log) => decodeEventLog({ abi: retryableAbi, data: log.data, topics: log.topics }))
  .find((event) => event.args.ticketId.toLowerCase() === ticketId.toLowerCase());
if (!scheduled) throw new Error(`Redeem transaction did not schedule the retryable: ${hash}`);

const retryHash = scheduled.args.retryTxHash;
console.log('Redeem scheduled. Checking execution transaction:', retryHash);
let retryReceipt;
try {
  retryReceipt = await publicClient.waitForTransactionReceipt({
    hash: retryHash,
    timeout: 120_000,
  });
} catch (error) {
  throw new Error(`No execution receipt yet for ${retryHash}. Check that hash on your L3 before retrying the ticket.`, { cause: error });
}
if (retryReceipt.status !== 'success') {
  throw new Error(`WETH gateway retryable execution failed: ${retryHash}. Retry before the ticket expires.`);
}
console.log('WETH gateway retryable redeemed:', retryHash);

